import {campusMapImage,loadRegions,drawRegions,addCampusBrand} from './campus-map.js?v=campus-layers-20261111';
import {uploadServiceURL} from './field-config.js';
export async function mountRegionEditor({getUser,isAdmin}){
 const section=document.createElement('section');section.innerHTML='<h2>校園地圖區域名稱</h2><p>v3 底圖與名稱為獨立圖層。選取名稱可改字或拖曳；儲存草稿僅限本機，發布後所有裝置更新。區位仍須現場核對。</p><div class="region-map" style="position:relative;max-width:1000px"><img style="width:100%;display:block" alt="v3 校園底圖"></div><label>區域<select></select></label><label>名稱<input maxlength="60"></label><label>左起 %<input type="number" min="0" max="100" step="0.1"></label><label>上起 %<input type="number" min="0" max="100" step="0.1"></label><button type="button" data-save>儲存本機草稿</button> <button type="button" data-publish>發布區域圖層</button> <button type="button" data-reset>還原已發布版本</button><p role="status"></p>';
 document.querySelector('#workspace').prepend(section);const map=section.querySelector('.region-map');map.querySelector('img').src=campusMapImage;addCampusBrand(map,{regions:false});const layer=document.createElement('div');layer.style.cssText='position:absolute;inset:0;touch-action:none';map.append(layer);const select=section.querySelector('select'),[name,x,y]=section.querySelectorAll('input'),status=section.querySelector('[role=status]'),key='danan-campus-region-v3-corrected-20261111-draft';let original,data,busy=false;
 try{original=await loadRegions();data=structuredClone(original);const draft=JSON.parse(localStorage.getItem(key)||'null');if(draft?.base===original.base&&Array.isArray(draft.regions)&&draft.regions.length===original.regions.length)data=draft;}catch(e){status.textContent=e.message;return;}
 for(const r of data.regions){const o=document.createElement('option');o.value=r.id;o.textContent=r.name;select.append(o)}
 const current=()=>data.regions.find(r=>r.id===select.value);
 function render(){drawRegions(layer,data);for(const label of layer.children){label.style.pointerEvents='auto';label.style.cursor='move';label.style.touchAction='none';}const r=current();name.value=r.name;x.value=r.x;y.value=r.y;for(const o of select.options)o.textContent=data.regions.find(r=>r.id===o.value).name;}
 select.onchange=render;for(const input of [name,x,y])input.onchange=()=>{if(busy||!isAdmin())return;const r=current();r.name=name.value.trim()||r.name;r.x=Math.max(0,Math.min(100,Number(x.value)||0));r.y=Math.max(0,Math.min(100,Number(y.value)||0));render();};
 let drag;layer.onpointerdown=e=>{if(busy||!isAdmin()||!e.target.dataset.region)return;select.value=e.target.dataset.region;const r=current(),box=layer.getBoundingClientRect();drag={id:e.pointerId,x:e.clientX,y:e.clientY,ox:r.x,oy:r.y,box};layer.setPointerCapture(e.pointerId);e.preventDefault();render();};layer.onpointermove=e=>{if(!drag||drag.id!==e.pointerId||!isAdmin())return;current().x=+Math.max(0,Math.min(100,drag.ox+(e.clientX-drag.x)/drag.box.width*100)).toFixed(2);current().y=+Math.max(0,Math.min(100,drag.oy+(e.clientY-drag.y)/drag.box.height*100)).toFixed(2);render();};layer.onpointerup=layer.onpointercancel=()=>{drag=null;};
 section.querySelector('[data-save]').onclick=()=>{try{localStorage.setItem(key,JSON.stringify(data));status.textContent='本機草稿已儲存，尚未發布。';}catch{status.textContent='儲存失敗，請檢查瀏覽器空間。'}};
 section.querySelector('[data-reset]').onclick=()=>{data=structuredClone(original);localStorage.removeItem(key);render();status.textContent='已還原發布版本。';};
 section.querySelector('[data-publish]').onclick=async()=>{if(busy||!isAdmin())return;busy=true;section.querySelectorAll('button,input,select').forEach(e=>e.disabled=true);status.textContent='正在發布…';try{const r=await fetch(uploadServiceURL+'/campus/regions',{method:'POST',headers:{Authorization:'Bearer '+await getUser().getIdToken(),'Content-Type':'application/json'},body:JSON.stringify({data,previous:original})});if(r.status===404)throw Error('發布服務尚未更新，需先部署新版 Worker');const result=await r.json();if(!r.ok)throw Error(result.error||'發布失敗');original=structuredClone(data);localStorage.removeItem(key);status.textContent='已提交 '+result.commit.slice(0,7)+'，部署完成後前台更新。';}catch(e){status.textContent=e.message+'；草稿仍保留。';try{localStorage.setItem(key,JSON.stringify(data));}catch{}}finally{busy=false;section.querySelectorAll('button,input,select').forEach(e=>e.disabled=false);}};render();
}
